mapper.select:
select recent.*
from(
    select m.*
    from ai_message m
    inner join ai_conversation c
    on c.id=m.conversation_id
    where m.conversation_id=#{conversationId}
    and c.user_id=#{userId}
    and c.status='ACTIVE'
    and m.role in('USER','ASSISTANT')
    order by m.id desc
    limit #{limit}
)recent
order by recent.id asc
